// Package referencecov holds Cloudrift's coverage of an outside reference catalog (pathfinding.cloud), measured by
// the benchmark in internal/blastradius. reference_coverage.json is generated by that test and checked in; the
// test fails when the file is out of date, so the Coverage page cannot drift from what the benchmark measures.
package referencecov

import (
	_ "embed"
	"encoding/json"
	"sync"
)

//go:embed reference_coverage.json
var raw []byte

// Statuses of one reference path.
const (
	Detected    = "detected"
	Partial     = "partial"
	NotDetected = "not_detected"
)

type Source struct {
	Name       string `json:"name"`
	URL        string `json:"url"`
	License    string `json:"license"`
	Commit     string `json:"commit"`
	Snapshot   string `json:"snapshot_date"`
	AWSRecords int    `json:"aws_records"`
	Excluded   string `json:"excluded"`
	Method     string `json:"method"`
}

type Totals struct {
	Paths          int     `json:"paths"`
	Detected       int     `json:"detected"`
	Partial        int     `json:"partial"`
	NotDetected    int     `json:"not_detected"`
	FalsePositives int     `json:"false_positives"`
	TrueNegatives  int     `json:"true_negatives"`
	Precision      float64 `json:"precision"`
	Recall         float64 `json:"recall"`
}

// Group is the coverage of one category or service.
type Group struct {
	Key         string `json:"key"`
	Name        string `json:"name"`
	Total       int    `json:"total"`
	Detected    int    `json:"detected"`
	Partial     int    `json:"partial"`
	NotDetected int    `json:"not_detected"`
}

type Path struct {
	ID       string   `json:"id"`
	Category string   `json:"category"`
	Service  string   `json:"service"`
	Status   string   `json:"status"`
	Required []string `json:"required"`
	Reason   string   `json:"reason,omitempty"`
	URL      string   `json:"url"`
}

type Report struct {
	Source     Source  `json:"source"`
	Totals     Totals  `json:"totals"`
	Categories []Group `json:"categories"`
	Services   []Group `json:"services"`
	Paths      []Path  `json:"paths"`
}

var (
	once   sync.Once
	loaded Report
)

// Load returns the embedded report.
func Load() Report {
	once.Do(func() { _ = json.Unmarshal(raw, &loaded) })
	return loaded
}
